1	use rand::seq::SliceRandom;
2	
3	use crate::actions::Action;
4	use crate::cards::CardRegistry;
5	use crate::combat;
6	use crate::events::GameEvent;
7	use crate::ids::{CardId, ObjectId, PlayerId};
8	use crate::mana;
9	use crate::sba::check_state_based_actions_with_registry;
10	use crate::stack;
11	use crate::state::{AwaitingAction, GameState, LogLevel};
12	use crate::triggers;
13	use crate::types::*;
14	
15	/// A decklist: card name -> count.
16	pub struct Decklist {
17	    pub entries: Vec<(String, u32)>,
18	}
19	
20	/// Configuration for setting up a game.
21	pub struct GameConfig {
22	    pub player_names: Vec<String>,
23	    pub decklists: Vec<Decklist>,
24	    pub starting_life: i32,
25	}
26	
27	/// Result of legal_actions: a list of actions plus an optional combat prompt.
28	/// When a combat prompt is present, the player should construct a
29	/// DeclareAttackers/DeclareBlockers action from it (not pick from the actions list).
30	pub struct LegalActions {
31	    pub actions: Vec<Action>,
32	    pub combat_prompt: Option<crate::actions::CombatPrompt>,
33	    /// Castable spells with valid target options, for interactive target selection.
34	    /// Each entry is one castable spell (collapsed view). The `actions` list still
35	    /// contains the fully-expanded CastSpell entries for LLM/random players.
36	    pub castable_spells: Vec<crate::actions::CastableSpell>,
37	}
38	
39	/// Check if Rooftop Storm is on the battlefield and provides a {0} alternative cost
40	/// for a Zombie creature spell cast by the given player.
41	fn rooftop_storm_applies(state: &GameState, registry: &CardRegistry, card_id: CardId, caster: PlayerId) -> bool {
42	    // Check if the spell is a Zombie creature spell.
43	    let is_zombie_creature = registry.card_data(card_id).map(|d| {
44	        d.card_types.contains(&CardType::Creature)
45	            && d.subtypes.iter().any(|s| s == "Zombie")
46	    }).unwrap_or(false);
47	    if !is_zombie_creature {
48	        return false;
49	    }
50	    // Check if the caster controls a Rooftop Storm on the battlefield.
51	    state.objects.values().any(|o| {
52	        o.zone == Zone::Battlefield
53	            && o.controller == caster
54	            && o.name == "Rooftop Storm"
55	    })
56	}
57	
58	/// Compute the effective mana cost of a spell after applying cost reduction effects.
59	/// Returns a reduced ManaCost (generic portion lowered, colored requirements unchanged).
60	pub fn effective_spell_cost(state: &GameState, registry: &CardRegistry, card_id: CardId, base_cost: &ManaCost, caster: PlayerId) -> ManaCost {
61	    use crate::types::{ContinuousEffect, SpellFilter};
62	
63	    // Check if the card has a custom cost modification (e.g., Blasphemous Act).
64	    if let Some(behavior) = registry.get(card_id) {
65	        if let Some(modified) = behavior.modified_cost(state, registry) {
66	            return modified;
67	        }
68	    }
69	
70	    let card_data = registry.card_data(card_id);
71	    let is_creature = card_data.as_ref()
72	        .map(|d| d.card_types.contains(&CardType::Creature))
73	        .unwrap_or(false);
74	    let subtypes: Vec<String> = card_data.as_ref()
75	        .map(|d| d.subtypes.clone())
76	        .unwrap_or_default();
77	
78	    // Gather all ReduceCost effects from permanents the caster controls.
79	    let mut total_reduction: u32 = 0;
80	    for obj in state.objects.values() {
81	        if obj.zone != Zone::Battlefield || obj.controller != caster {
82	            continue;
83	        }
84	        if let Some(behavior) = registry.get(obj.card_id) {
85	            for effect in &behavior.card_data().continuous_effects {
86	                if let ContinuousEffect::ReduceCost { reduction, filter } = effect {
87	                    let applies = match filter {
88	                        SpellFilter::CreatureSpells => is_creature,
89	                        SpellFilter::CreatureWithSubtype(sub) => {
90	                            is_creature && subtypes.iter().any(|s| s == sub)
91	                        }
92	                    };
93	                    if applies {
94	                        total_reduction += reduction;
95	                    }
96	                }
97	            }
98	        }
99	    }
100	
101	    // Rooftop Storm's alternative cost is handled via the alternative_cost field
102	    // on CastSpell actions (see rooftop_storm_applies() and action generation).
103	    // It is NOT a cost reduction — it's an alternative cost chosen at cast time.
104	
105	    if total_reduction == 0 {
106	        return base_cost.clone();
107	    }
108	
109	    // Apply reduction to generic mana first, keeping colored requirements.
110	    let mut remaining_reduction = total_reduction;
111	    let mut new_symbols = Vec::new();
112	    for sym in &base_cost.symbols {
113	        match sym {
114	            ManaSymbol::Generic(n) => {
115	                if remaining_reduction >= *n {
116	                    remaining_reduction -= *n;
117	                    // Reduced to zero, omit this symbol.
118	                } else {
119	                    new_symbols.push(ManaSymbol::Generic(*n - remaining_reduction));
120	                    remaining_reduction = 0;
121	                }
122	            }
123	            other => new_symbols.push(other.clone()),
124	        }
125	    }
126	    ManaCost::new(new_symbols)
127	}
128	
129	/// Compute all legal actions for the player who currently needs to act.
130	pub fn legal_actions(state: &GameState, registry: &CardRegistry) -> LegalActions {
131	    if state.is_game_over() {
132	        return LegalActions { actions: vec![], combat_prompt: None, castable_spells: vec![] };
133	    }
134	
135	    // If we're waiting for a specific action (attackers, blockers, discard).
136	    if let Some(awaiting) = &state.awaiting_action {
137	        return match awaiting {
138	            AwaitingAction::DeclareAttackers => {
139	                let active = state.active_player;
140	                let eligible = combat::eligible_attackers(state, active, registry);
141	                let defending = state.opponent(active);
